    items = [b(5, "a"), b(5, "b")]
    assert chunk(items, max_items=10, max_bytes=10) == [items]


def test_preserves_order():
    items = [b(3, t) for t in "abcdefg"]
    flat = [x for batch in chunk(items, max_items=2, max_bytes=7) for x in batch]
    assert flat == items


